export const DEFAULT_FLEET_SONG='D3+A3:2 R:1 D4:1 F4:1 A4:1 E4:2\nC3+G3:2 R:1 E4:1 G4:1 D4:1 A3:2';
export function parseFleetSong(source){
 if(typeof source!=='string'||source.length>4096)throw Error('Composition must fit within 4,096 characters.');
 const tokens=source.trim().split(/\s+/);if(!source.trim()||tokens.length>256)throw Error('Write 1–256 notes, chords or rests.');
 let beats=0;const events=tokens.map((token,index)=>{const match=token.match(/^([A-GR][#b]?[1-7]?(?:\+[A-G][#b]?[1-7]){0,3}):(\d+(?:\.\d+)?)$/);if(!match)throw Error('Note '+(index+1)+': use C4:1, C4+E4+G4:2 or R:1.');const duration=Number(match[2]);if(duration<.25||duration>16)throw Error('Note lengths must be 0.25–16 beats.');const frequencies=match[1]==='R'?[]:match[1].split('+').map(note=>{const n=note.match(/^([A-G])([#b]?)([1-7])$/);if(!n)throw Error('Every note needs an octave, for example C4.');const midi=(Number(n[3])+1)*12+{C:0,D:2,E:4,F:5,G:7,A:9,B:11}[n[1]]+(n[2]==='#'?1:n[2]==='b'?-1:0);return 440*2**((midi-69)/12);});const event={at:beats,duration,frequencies};beats+=duration;return event;});
 if(beats>512)throw Error('Composition is limited to 512 beats.');return {events,beats};
}
export class FleetScore{
 constructor(){this.enabled=false;this.ctx=null;this.voices=new Set();this.buffer=null;this.fileName='';this.generation=0;this.volume=.3;this.lastBeat=-1;this.lastTime=-1;this.song='';}
 async enable(){const request=this.generation,C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)throw Error('Audio is unavailable in this browser.');if(!this.ctx){this.ctx=new C();this.bus=this.ctx.createGain();this.bus.gain.value=this.volume;this.bus.connect(this.ctx.destination);}await this.ctx.resume();if(request===this.generation)this.enabled=true;}
 silence(){for(const source of this.voices){try{source.stop();}catch{}}this.voices.clear();this.uploadSource=null;this.lastBeat=-1;this.lastTime=-1;}
 stop(){this.generation++;this.enabled=false;this.silence();}
 async upload(file){if(!file||file.size>32*1024*1024)throw Error('Choose an audio file smaller than 32 MB.');if(!/^(audio\/|application\/ogg)/.test(file.type)&&! /\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(file.name))throw Error('Choose MP3, WAV, OGG, M4A, AAC or FLAC audio.');const request=++this.generation;await this.enable();if(request!==this.generation)return false;const buffer=await this.ctx.decodeAudioData(await file.arrayBuffer());if(request!==this.generation)return false;if(buffer.duration>900)throw Error('Choose a track shorter than 15 minutes.');this.silence();this.buffer=buffer;this.fileName=file.name;return true;}
 useComposition(source){const score=parseFleetSong(source);this.generation++;this.silence();this.buffer=null;this.fileName='';this.song=source;this.score=score;}
 update(program,running,{gain=1}={}){if(!this.ctx||!this.enabled)return;const time=Math.max(0,(program?.time||0)-(program?.settings.countIn||0));if(!running||gain<=0||!program?.running||!program?.enabled||program.time<program.settings.countIn){if(this.voices.size)this.silence();return;}
  this.bus.gain.setTargetAtTime(this.volume*Math.max(0,Math.min(1,gain)),this.ctx.currentTime,.04);
  const jump=this.lastTime<0||time<this.lastTime||time-this.lastTime>.5;this.lastTime=time;
  if(this.buffer){if(!this.uploadSource||jump){this.silence();this.lastTime=time;const source=this.ctx.createBufferSource();source.buffer=this.buffer;source.loop=true;source.connect(this.bus);this.voices.add(source);source.onended=()=>{this.voices.delete(source);source.disconnect();};source.start(0,time%this.buffer.duration);this.uploadSource=source;}return;}
  const source=program.settings.song||DEFAULT_FLEET_SONG;if(source!==this.song){this.useComposition(source);this.lastTime=time;}if(!this.score)this.score=parseFleetSong(source);
  const beat=time*program.settings.bpm/60,cycle=Math.floor(beat/this.score.beats),local=beat%this.score.beats;
  for(const [i,event]of this.score.events.entries()){const at=cycle*this.score.beats+event.at,key=cycle*256+i;if(event.at<=local&&local<event.at+event.duration&&(jump||this.lastBeat!==key)){this.lastBeat=key;const duration=(event.at+event.duration-local)*60/program.settings.bpm;for(const frequency of event.frequencies){const o=this.ctx.createOscillator(),gain=this.ctx.createGain(),now=this.ctx.currentTime;o.type='triangle';o.frequency.value=frequency;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.045/Math.max(1,event.frequencies.length),now+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+Math.max(.04,duration));o.connect(gain);gain.connect(this.bus);this.voices.add(o);o.onended=()=>{this.voices.delete(o);o.disconnect();gain.disconnect();};o.start();o.stop(now+Math.max(.05,duration)+.02);}break;}}
 }
 dispose(){this.generation++;this.stop();this.buffer=null;this.ctx?.close?.();this.ctx=null;}
}
const escape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fleetScoreMarkup(song=DEFAULT_FLEET_SONG){return `<section class="fleetScore"><h3>Soundtrack studio</h3><p>Write notes or chords as pitch:beats. R is a rest. This composition loops at the fleet BPM and follows its clock.</p><label>Composition<textarea data-fleet-song rows="4" maxlength="4096" spellcheck="false">${escape(song)}</textarea></label><button data-score-use>Use composition & enable audio</button><label>Or choose your own audio<input data-score-file type="file" accept="audio/*,.ogg,.flac"></label><p class="hint">Files stay on this device for this session. Set the track’s BPM above to time the choreography; uploading does not detect beats. Saved fleets include written notes; reattach audio after reopening.</p><label>Soundtrack volume<input data-score-volume type="range" min="0" max=".7" step=".01" value=".3"></label><button data-score-stop>Mute soundtrack</button><p data-score-status role="status">Audio starts after you enable it and resume a running fleet.</p></section>`;}
export function mountFleetScore(root,engine,onSong){const q=s=>root.querySelector(s);if(!q('[data-fleet-song]'))return;const status=q('[data-score-status]');if(engine.fileName)status.textContent='Attached: '+engine.fileName;q('[data-score-volume]').value=engine.volume;const guard=fn=>async()=>{try{await fn();}catch(e){status.textContent=e.message;}};
 q('[data-score-use]').addEventListener('click',guard(async()=>{const song=q('[data-fleet-song]').value;engine.useComposition(song);onSong(song);await engine.enable();status.textContent='Composition ready. Resume a running fleet to hear it.';}));
 q('[data-score-file]').addEventListener('change',guard(async()=>{const file=q('[data-score-file]').files?.[0];if(!file)return;if(await engine.upload(file))status.textContent='Attached: '+engine.fileName+'. Resume the fleet to play.';}));
 q('[data-score-volume]').addEventListener('input',()=>engine.volume=Number(q('[data-score-volume]').value));q('[data-score-stop]').addEventListener('click',()=>{engine.stop();status.textContent='Soundtrack muted.';});
}
